void buffer_copy_string_len(buffer *b, const char *s, size_t s_len) { /* <=== buffer_copy_string_len */ 
	force_assert(NULL != b);
	force_assert(NULL != s || s_len == 0);

	buffer_string_prepare_copy(b, s_len);

	if (0 != s_len) memcpy(b->ptr, s, s_len);

	buffer_commit(b, s_len);
}

void buffer_copy_buffer(buffer *b, const buffer *src) { /* <=== buffer_copy_buffer */ 
	if (NULL == src || 0 == src->used) {
		buffer_string_prepare_copy(b, 0);
		b->used = 0; /* keep special empty state for now */
	} else {
		buffer_copy_string_len(b, src->ptr, buffer_string_length(src));
	}
}

char* buffer_string_prepare_copy(buffer *b, size_t size) { /* <=== buffer_string_prepare_copy */ 
	force_assert(NULL != b);
	force_assert(size + 1 > size);

	buffer_alloc(b, size + 1);

	b->used = 1;
	b->ptr[0] = '\0';

	return b->ptr;
}

char* buffer_string_prepare_append(buffer *b, size_t size) { /* <=== buffer_string_prepare_append */ 
	force_assert(NULL !=  b);

	if (buffer_string_is_empty(b)) {
		return buffer_string_prepare_copy(b, size);
	} else {
		size_t req_size = b->used + size;

		/* not empty, b->used already includes a terminating 0 */
		force_assert(req_size >= b->used);

		/* check for overflow: unsigned overflow is defined to wrap around */
		force_assert(req_size >= b->used);

		buffer_realloc(b, req_size);

		return b->ptr + b->used - 1;
	}
}

void log_failed_assert(const char *filename, unsigned int line, const char *msg) { /* <=== log_failed_assert */ 
	/* can't use buffer here; could lead to recursive assertions */
	fprintf(stderr, "%s.%u: %s\n", filename, line, msg);
	print_backtrace(stderr);
	fflush(stderr);
	abort();
}

void buffer_commit(buffer *b, size_t size) /* <=== buffer_commit */ 
{
	force_assert(NULL != b);
	force_assert(b->size > 0);

	if (0 == b->used) b->used = 1;

	if (size > 0) {
		/* check for overflow: unsigned overflow is defined to wrap around */
		force_assert(b->used + size > b->used);

		force_assert(b->used + size <= b->size);
		b->used += size;
	}

	b->ptr[b->used - 1] = '\0';
}

static inline int buffer_is_empty(const buffer *b) { /* <=== buffer_is_empty */ 
	return NULL == b || 0 == b->used;
}

static inline size_t buffer_string_length(const buffer *b) { /* <=== buffer_string_length */ 
	return NULL != b && 0 != b->used ? b->used - 1 : 0;
}

void buffer_append_string(buffer *b, const char *s) { /* <=== buffer_append_string */ 
	buffer_append_string_len(b, s, NULL != s ? strlen(s) : 0);
}

static void buffer_alloc(buffer *b, size_t size) { /* <=== buffer_alloc */ 
	force_assert(NULL != b);
	if (0 == size) size = 1;

	if (size <= b->size) return;

	if (NULL != b->ptr) free(b->ptr);

	b->used = 0;
	b->size = buffer_align_size(size);
	b->ptr = malloc(b->size);

	force_assert(NULL != b->ptr);
}

void buffer_append_string_len(buffer *b, const char *s, size_t s_len) { /* <=== buffer_append_string_len */ 
	char *target_buf;

	force_assert(NULL != b);
	force_assert(NULL != s || s_len == 0);

	target_buf = buffer_string_prepare_append(b, s_len);

	if (0 == s_len) return; /* nothing to append */

	memcpy(target_buf, s, s_len);

	buffer_commit(b, s_len);
}

